```c
#include <stdio.h>
#include <stdlib.h>

// Function to get value from an array at a given index
int getValueFromArray(int arr[], int size, int index) {
    if (index >= 0 && index < size) {
        return arr[index];
    } else {
        return -1;
    }
}

int main() {
    // Read the size of the array from standard input
    int size;
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    // Allocate memory for the array
    int *arr = (int *)malloc(size * sizeof(int));
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Read the elements of the array from standard input
    printf("Enter %d elements of the array:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    // Read the index to access from standard input
    int index;
    printf("Enter the index to access: ");
    scanf("%d", &index);

    // Call getValueFromArray and get the result
    int value = getValueFromArray(arr, size, index);

    // Free the allocated memory
    free(arr);

    // Return the result as the exit code
    return value;
}
```

### Explanation:
1. **getValueFromArray Function**:
   - This function takes an array of integers, its size, and an index as parameters.
   - It checks if the index is within the bounds of the array (i.e., non-negative and less than the size).
