#define MAX_BUFFER_SIZE 1024 // Maximum size of the buffer

// Function to calculate the checksum of a buffer
unsigned char calculateChecksum(unsigned char *buffer, size_t length) {
    unsigned char sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += buffer[i];
    }
    return sum;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *inputFile = argv[1];
    const char *outputFile = argv[2];

    // Open the input file in binary read mode
    FILE *input = fopen(inputFile, "rb");
    if (!input) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    // Open or create the output file in binary write mode
    FILE *output = fopen(outputFile, "wb");
    if (!output) {
        perror("Failed to open output file");
        fclose(input);
        return EXIT_FAILURE;
    }

    // Allocate buffer to read data from the input file
    unsigned char buffer[MAX_BUFFER_SIZE];
    size_t bytesRead;

    while ((bytesRead = fread(buffer, 1, sizeof(buffer), input)) > 0) {
        // Calculate the checksum of the current chunk of data
        unsigned char checksum = calculateChecksum(buffer, bytesRead);

        // Write the number of bytes read and the checksum to the output file
        if (fwrite(&bytesRead, sizeof(size_t), 1, output) != 1 || fwrite(&checksum, 1, 1, output) != 1) {
            perror("Failed to write data to output file");
            fclose(input);
            fclose(output);
            return EXIT_FAILURE;
        }
    }

    // Check if the input file was completely read
    if (ferror(input)) {
        perror("Error reading input file");
        fclose(input);
        fclose(output);
        return EXIT_FAILURE;
    }

    // Close both files
    fclose(input);
    fclose(output);

    printf("Checksum and byte count saved to %s\n", outputFile);

    return EXIT_SUCCESS;
}
```

### Explanation:
1. **Command Line Arguments**: The program expects two command-line arguments: the input file and the output file.
2. **File Opening**: It opens the input file in binary read mode (`"rb"`) and the output file in binary write mode (`"wb"`).
3. **Buffer Reading**: It reads data from the input file into a buffer of size `MAX_BUFFER_SIZE`.
4. **Checksum Calculation**: For each chunk of data read, it calculates the checksum using the `calculateChecksum` function.
5. **Data Writing**: It writes the number of bytes read and the checksum to the output file.
6. **Error Handling**: The program checks for errors during file operations and prints appropriate error messages.

### Usage:
To compile and run the program, save it to a file (e.g., `checksum.c`), then use the following commands:

```sh
