['Certainly! Below is a Python code snippet that demonstrates how to create a decorator to bind a function to a URL, and then run a system command to ping a specified URL when the URL is accessed.

```python
import os
from functools import wraps

# Decorator to bind a function to a URL
def route(url):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        wrapper.url = url
        return wrapper
    return decorator

@route('/ping')
def ping():
    url = "example.com"  # Replace with the actual URL you want to ping
    try:
        output = os.system(f'ping {url}')
        if output == 0:
            return f"Ping to {url} was successful."
        else:
            return f"Ping to {url} failed."
    except Exception as e:
        return f"An error occurred: {str(e)}"

# Function to simulate routing
def route_handler(url):
    for func in globals().values():
        if hasattr(func, 'url') and func.url == url:
            return func()
    return "URL not found."

# Example usage
if __name__ == "__main__":
    requested_url = "/ping"
    result = route_handler(requested_url)
    print(result)
```

### Explanation:

1. **Decorator `route`**:
   - This decorator takes a URL as an argument and returns another decorator.
