#include <stdarg.h>

// Function to execute a command
void execute_command(const char *command) {
    int status = system(command);
    if (status != 0) {
        perror("Command execution failed");
    }
}

// Print function that dynamically creates the command string
char* create_command_string(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Determine the length of the resulting string
    int size = vsnprintf(NULL, 0, format, args);
    if (size < 0) {
        perror("Error determining string size");
        return NULL;
    }

    // Allocate memory for the command string
    char *buffer = malloc(size + 1);
    if (!buffer) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Create the command string
    int result = vsnprintf(buffer, size + 1, format, args);
    if (result < 0) {
        perror("Error creating command string");
        free(buffer);
        return NULL;
    }

    va_end(args);
    return buffer;
}

int main() {
    // Define the arguments for the command
    const char *path = "/home/user";  // Replace with your desired path

    // Create the command string using the print function
    char *command_string = create_command_string("ls -l %s", path);
    if (!command_string) {
        return EXIT_FAILURE;
    }

    // Execute the command
    execute_command(command_string);

    // Free the allocated memory for the command string
    free(command_string);

    return EXIT_SUCCESS;
}
```

### Explanation:
