```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to trim trailing whitespaces from a string
void trimTrailingWhitespaces(char *str) {
    if (str == NULL || *str == '\0') {
        return;
    }
    char *end = str + strlen(str) - 1;
    while (end > str && (*end == ' ' || *end == '\t' || *end == '\n')) {
        end--;
    }
    *(end + 1) = '\0';
}

int main(int argc, char *argv[]) {
    // First if statement: check to make sure that the user provided exactly one argument
    if (argc != 2) {
        fprintf(stderr, "Error: Please provide exactly one argument.\n");
        return EXIT_FAILURE;
    }

    // Second line: get the argument from the command line and store it in a variable called input
    char *input = argv[1];

    // Third line: print the argument
    printf("Original Argument: %s\n", input);

    // Fourth line: trim the trailing whitespace from the argument
    trimTrailingWhitespaces(input);

    // Fifth line: print the argument again
    printf("Argument after trimming whitespaces: %s\n", input);

    // Sixth line: exit the program
    return EXIT_SUCCESS;
}
```

### Explanation:
1. **Error Checking**: The first `if` statement checks if exactly one command-line argument is provided (`argc != 2`). If not, it prints an error message and exits with a failure status.
