```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_USERNAME_LENGTH 256

// Function to handle the /hello URL request
void http_hello_page(FILE *request_stream, FILE *response_stream) {
    char username[MAX_USERNAME_LENGTH];
    char outputbuf[1024];

    // Read the request body (username)
    if (!fgets(username, sizeof(username), request_stream)) {
        fprintf(stderr, "Failed to read username from request\n");
        return;
    }

    // Remove newline character if present
    username[strcspn(username, "\n")] = 0;

    // Construct the response body (HTML page)
    snprintf(outputbuf, sizeof(outputbuf),
             "<html><head><title>Hello Page</title></head>"
             "<body><h1>Hello, %s!</h1></body></html>", username);

    // Write the response body to the response stream
    fprintf(response_stream, "Content-Length: %zu\r\n", strlen(outputbuf));
    fprintf(response_stream, "\r\n");
    fprintf(response_stream, "%s", outputbuf);

    // Close the response stream (this is a simplified example; in practice, you might want to flush or handle errors)
    fflush(response_stream);
}

int main() {
    // Example usage: Simulate reading from and writing to files
    FILE *request_stream = fopen("request.txt", "r");
    if (!request_stream) {
        perror("Failed to open request file");
        return EXIT_FAILURE;
    }

    FILE *response_stream = fopen("response.txt", "w");
    if (!response_stream) {
        perror("Failed to open response file");
